request.query:
query FetchEnrichedContent($id: ID!) {
      product(id: $id) {
        id
        title
        handle
        status
        productType
        tags
        descriptionHtml
        contentStatus: metafield(namespace: "custom", key: "content_status") { value }
        summaryPoints: metafield(namespace: "custom", key: "summary_points") { value }
        whyRecommend: metafield(namespace: "custom", key: "why_recommend") { value }
        howToUse: metafield(namespace: "custom", key: "how_to_use") { value }
        specs: metafield(namespace: "custom", key: "specs") {
          references(first: 50) {
            edges {
              node {
                ... on Metaobject {
                  label: field(key: "label") { value }
                  value: field(key: "value") { value }
                }
              }
            }
          }
        }
        faq: metafield(namespace: "custom", key: "faq") {
          references(first: 50) {
            edges {
              node {
                ... on Metaobject {
                  question: field(key: "question") { value }
                  answer: field(key: "answer") { value }
                }
              }
            }
          }
        }
        complementaryProducts: metafield(namespace: "custom", key: "complementary_products") {
          references(first: 50) {
            edges {
              node {
                ... on Product { id title }
              }
            }
          }
        }
        originalTitle: metafield(namespace: "custom", key: "original_title") { value }
        originalDescriptionHtml: metafield(namespace: "custom", key: "original_description_html") { value }
        relatedGuides: metafield(namespace: "custom", key: "related_guides") {
          references(first: 50) {
            edges {
              node {
                ... on Article { id handle title }
              }
            }
          }
        }
        relatedGuidesSource: metafield(namespace: "custom", key: "related_guides_source") { value }
        idealFor: metafield(namespace: "custom", key: "ideal_for") { value }
      }
    }
